int main(){static_assert(Proto::VERSION==2,"wire version");static_assert(Proto::LABELS_VERSION==3,"label version");static_assert(Proto::FRAME_SIZE==32,"fixed frame");static_assert(Proto::ACTUATE_BATCH==14,"batch opcode");Proto::Frame f;Proto::computeMeta(f,1,0,32);assert(Proto::compatible(f,0,32));auto old=f;old.bytes[1]=1;old.bytes[31]=Proto::crc8(old.bytes,31);assert(!Proto::valid(old));old=f;Proto::payload(old)[8]=2;old.bytes[31]=Proto::crc8(old.bytes,31);assert(Proto::valid(old)&&!Proto::compatible(old,0,32));old=f;Proto::put32(Proto::payload(old),0x30918170UL);old.bytes[31]=Proto::crc8(old.bytes,31);assert(!Proto::compatible(old,0,32));Actuator::Engine engine;uint8_t p[9];Proto::put32(p,1);Proto::put32(p+4,Proto::MODEL_ID);p[8]=2;Proto::make(f,Proto::HELLO,0,0,p,9);Proto::Frame out;assert(engine.onFrame(f,out,0));assert(Proto::op(out)==Proto::ERROR_REPLY&&Proto::payload(out)[1]==Proto::BAD_MODEL);assert(!engine.outputs().drive&&!engine.outputs().lights&&!engine.outputs().wiper&&!engine.outputs().horn);}
